INSERT INTO public.exam_config (class, is_open, total_questions, time_limit_minutes, passing_score, max_attempts, show_results_to_students)
INSERT INTO public.questions (class, subject_tag, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option)
VALUES
  (12, 'Keyboard Shortcuts', 'easy', 'Which key on a Windows keyboard is used to capture a screenshot of your entire screen?', 'PrtSc (Print Screen)', 'Page Down', 'Pause/Break', 'Scroll Lock', 'a'),
  (12, 'Keyboard Shortcuts', 'easy', 'When a file or folder is selected on Windows, pressing which function key lets you RENAME it immediately?', 'F4', 'F1', 'F2', 'F8', 'c'),
  (12, 'Keyboard Shortcuts', 'easy', 'What does pressing Alt + F4 do on a Windows computer?', 'Turns on Bluetooth', 'Closes the currently active app or window', 'Opens four new folders', 'Increases speaker volume', 'b'),
  (12, 'Keyboard Shortcuts', 'easy', 'In a browser, pressing Ctrl and the "+" (plus) key together does what?', 'Adds a new user account', 'Increases internet speed', 'Opens calculator', 'Zooms in to make text and images appear larger', 'd'),
  (12, 'Keyboard Shortcuts', 'easy', 'After zooming in on a webpage, pressing Ctrl + 0 (zero) does what?', 'Deletes the webpage', 'Resets the page zoom back to normal (100%)', 'Mutes computer sound', 'Closes all tabs', 'b'),
  (12, 'Keyboard Shortcuts', 'easy', 'When filling out an online form (like Name, Roll No, Class), pressing the Tab key usually does what?', 'Moves the cursor neatly to the next input box', 'Submits the form immediately', 'Closes the browser tab', 'Erases what you typed', 'a'),
  (12, 'Keyboard Shortcuts', 'easy', 'If you step away from a computer for a minute, which Windows shortcut immediately LOCKS your screen?', 'Ctrl + L', 'Alt + L', 'Windows Key + L', 'Windows Key + O', 'c'),
  (12, 'Keyboard Shortcuts', 'medium', 'Which Windows shortcut minimizes all open windows at once so you can see the Desktop?', 'Alt + D', 'Ctrl + D', 'Windows Key + P', 'Windows Key + D', 'd'),
  (12, 'Keyboard Shortcuts', 'medium', 'You accidentally closed an important tab in Chrome/Edge! Which lifesaver shortcut reopens the last closed tab?', 'Ctrl + Alt + Z', 'Shift + F5', 'Alt + Home', 'Ctrl + Shift + T', 'd'),
  (12, 'Keyboard Shortcuts', 'medium', 'What happens when you delete a file using Shift + Delete instead of just pressing Delete?', 'It moves the file to Desktop', 'It copies the file twice', 'It permanently deletes the file without sending it to the Recycle Bin', 'Nothing happens', 'c'),
  (12, 'Keyboard Shortcuts', 'medium', 'Which Windows shortcut opens File Explorer ("This PC" / Folders) directly?', 'Alt + E', 'Windows Key + F', 'Windows Key + E', 'Ctrl + E', 'c'),
  (12, 'Keyboard Shortcuts', 'medium', 'While typing a sentence, holding Ctrl and pressing Backspace (Ctrl + Backspace) erases what?', 'Only one single letter', 'The entire document', 'Only punctuation marks', 'The entire word to the left of the cursor at once', 'd'),
  (12, 'Keyboard Shortcuts', 'medium', 'Which function key toggles Full-Screen mode ON or OFF in almost all web browsers?', 'F3', 'F7', 'F11', 'F1', 'c'),
  (12, 'Keyboard Shortcuts', 'medium', 'If a program freezes on Windows, which direct shortcut opens Task Manager immediately?', 'Ctrl + Alt + P', 'Ctrl + Shift + Esc', 'Windows Key + M', 'Shift + Tab', 'b'),
  (12, 'Keyboard Shortcuts', 'hard', 'Which modern Windows shortcut lets you drag and capture a screenshot of just ONE selected area of your screen?', 'Alt + S', 'Ctrl + F4', 'Windows Key + Shift + S', 'Ctrl + P', 'c'),
  (12, 'Keyboard Shortcuts', 'hard', 'In Word, Google Docs, or Notepad, which shortcut opens "Find and Replace" to swap a repeated word across the whole file?', 'Ctrl + M', 'Ctrl + W', 'Ctrl + J', 'Ctrl + H', 'd'),
  (12, 'Keyboard Shortcuts', 'hard', 'In a web browser, pressing Ctrl + L (or Alt + D) quickly highlights what?', 'The top Address / URL bar so you can type a website or search immediately', 'Your computer wallpaper', 'The Recycle Bin', 'The bottom footer of the webpage', 'a'),
  (12, 'Keyboard Shortcuts', 'hard', 'In Word, Google Docs, or email apps, pressing Ctrl + K on selected text lets you insert what?', 'An audio recording', 'A clickable hyperlink (website link)', 'A page break', 'A password lock', 'b'),
  (12, 'Computer Hardware', 'easy', 'Which newer oval-shaped reversible charging/data port is found on almost all modern Android phones and newer laptops?', 'PS/2 round port', 'USB Type-C (USB-C)', 'VGA port', 'CD-ROM slot', 'b'),
  (12, 'Computer Hardware', 'easy', 'What do we call the main circuit board inside a computer that connects the processor, RAM, storage, and ports together?', 'Dashboard', 'Motherboard', 'Whiteboard', 'Clipboard', 'b'),
  (12, 'Computer Hardware', 'easy', 'If a wireless mouse stops moving the cursor on screen, what is the FIRST simple hardware thing you should check?', 'Reinstall Windows immediately', 'Buy a new monitor', 'Delete your files', 'Check if its battery is low or its tiny power switch underneath is turned OFF', 'd'),
  (12, 'Computer Hardware', 'easy', 'A pen-like tool used by digital artists and students to write or draw neatly on a tablet screen is called a:', 'Stylus', 'Laser printer', 'Router antenna', 'Thumb drive', 'a'),
  (12, 'Computer Hardware', 'easy', 'Which storage capacity is LARGER when comparing a pendrive or laptop storage?', '1 Gigabyte (1 GB)', '1 Terabyte (1 TB)', '1 Kilobyte (1 KB)', '1 Megabyte (1 MB)', 'b'),
  (12, 'Computer Hardware', 'easy', 'Roughly how many Gigabytes (GB) make 1 Terabyte (TB) on a hard drive?', 'About 50 GB', 'About 2 GB', 'About 10 GB', 'About 1,000 GB (1,024 GB)', 'd'),
  (12, 'Computer Hardware', 'easy', 'Before pulling out a USB pendrive while files are copying, why should you wait or click "Eject"?', 'The keyboard will lock', 'It uses up Wi-Fi data', 'Pulling it out mid-write can corrupt or damage the files being saved', 'Otherwise the monitor turns black forever', 'c'),
  (12, 'Computer Hardware', 'medium', 'Which computer component is specially helpful for smooth 3D video editing, animation, and modern games?', 'Floppy drive', 'Ink cartridge', 'RJ45 plug', 'GPU (Graphics Card / Graphics Processor)', 'd'),
  (12, 'Computer Hardware', 'medium', 'Why should you NEVER block the air vents on the bottom of a laptop by placing it deep into a thick blanket for hours?', 'It deletes browser bookmarks', 'It makes the screen brightness drop to zero', 'Blocked vents trap heat inside, causing overheating, slow performance, and battery wear', 'It disconnects Bluetooth earbuds', 'c'),
  (12, 'Computer Hardware', 'medium', 'A desktop monitor is turned ON, its power light is blinking, and it says "No Signal." What is the most likely practical cause?', 'The Recycle Bin is full', 'Either the CPU cabinet is OFF or the HDMI/VGA display cable between the CPU and monitor is loose', 'The internet website is down', 'Caps Lock is pressed on the keyboard', 'b'),
  (12, 'Computer Hardware', 'medium', 'What is the difference between putting a laptop to "Sleep" versus "Shut Down"?', 'Sleep keeps open work ready in low-power memory for instant wake-up; Shut Down closes everything completely', 'Shut Down uses more battery than playing games', 'Both are identical', 'Sleep erases all saved files', 'a'),
  (12, 'Computer Hardware', 'medium', 'What does screen resolution like "1920 × 1080 (Full HD)" describe on a monitor or phone?', 'The weight of the monitor in grams', 'The grid of tiny pixels (width × height) that makes up the sharpness of the display', 'How many files can fit on the desktop', 'How loud the speakers are', 'b'),
  (12, 'Computer Hardware', 'medium', 'An "All-in-One" desktop PC in a modern lab has no separate tower box on the desk. Where are its processor, RAM, and SSD located?', 'Built neatly right behind the monitor screen itself', 'Inside the mouse', 'On the internet cloud only', 'Inside the keyboard spacebar', 'a'),
  (12, 'Computer Hardware', 'medium', 'Why do ink-tank or laser printers usually cost much less per page for a school office than tiny cheap ink-cartridge printers?', 'They only print on Sundays', 'They require no electricity', 'They do not use paper', 'Refill ink bottles and toner print thousands of pages at a fraction of the cost per page', 'd'),
  (12, 'Computer Hardware', 'hard', 'What does a "60Hz" vs "120Hz" refresh rate on a phone or monitor screen mean in everyday use?', 'The Wi-Fi password length', 'How many apps can be installed', 'How many hours the battery lasts', 'How many times per second the screen updates the image — higher feels smoother while scrolling', 'd'),
  (12, 'Computer Hardware', 'hard', 'On headphones with a single 3.5mm plug (TRRS) used on laptops and phones, what does that single plug carry?', 'Internet Wi-Fi signal', 'Printer ink levels', 'Screen brightness power', 'Left audio, Right audio, AND Microphone voice signal together', 'd'),
  (12, 'Computer Hardware', 'hard', 'What is "Surge Protection" on a good computer extension spike-guard?', 'A tool that blocks pop-up ads', 'A feature that speeds up typing', 'Protection that shields connected computers from sudden high-voltage electricity spikes', 'A waterproof cover for monitors', 'c'),
  (12, 'Computer Hardware', 'hard', 'If your phone says "Storage Almost Full (98% used)", which action frees up real internal storage space?', 'Changing the lock-screen wallpaper', 'Backing up large old videos/downloads to cloud or PC and deleting unneeded heavy files/apps', 'Lowering screen brightness', 'Turning on Airplane Mode', 'b'),
  (12, 'Application Software & OS', 'easy', 'On Windows, files ending in ".exe" (or ".apk" on Android) are what kind of files?', 'Spreadsheet charts', 'Plain text essays', 'Application installer / executable program files (only run from trusted official sources!)', 'Family vacation photos', 'c'),
  (12, 'Application Software & OS', 'easy', 'Before editing an important project presentation, why is naming files clearly like "Science_Poster_v2_Final.pptx" better than "asdf123.pptx"?', 'Clear file names let you and your teammates find the right version in seconds without confusion', 'Long names increase RAM', 'It changes slide colors automatically', 'Computers refuse to save short names', 'a'),
  (12, 'Application Software & OS', 'easy', 'What does the "Spell Check" wavy red underline in Word or Google Docs indicate?', 'A word that may have a spelling typo so you can review and fix it', 'That the computer has a virus', 'That the sentence will be deleted automatically', 'That the font is bold', 'a'),
  (12, 'Application Software & OS', 'easy', 'If a single app stops responding ("Not Responding") on Windows, how can you close JUST that stuck app without unplugging the whole PC?', 'Pull the electric plug from the wall', 'Open Task Manager, select the frozen app, and click "End Task"', 'Tap the monitor glass', 'Format the hard drive', 'b'),
  (12, 'Application Software & OS', 'easy', 'What is "Open-Source Software" (such as Linux, VLC, Blender, or LibreOffice)?', 'Software that works only for 1 hour', 'Broken trial software', 'Software whose source code is openly shared so anyone can use, study, and improve it legally', 'Software that leaves your computer unlocked to strangers', 'c'),
  (12, 'Application Software & OS', 'easy', 'When you install a new PDF app and Windows asks which "Default App" should open .pdf files, what does that setting control?', 'Whether printing is allowed', 'How fast the internet runs', 'Which user owns the computer', 'Which program opens automatically whenever you double-click any .pdf file', 'd'),
  (12, 'Application Software & OS', 'easy', 'In Google Docs or Microsoft 365 Online, what is a huge everyday advantage of "Auto-Save" to the cloud?', 'It writes your homework by itself', 'It works without turning on the screen', 'It prints every page automatically', 'Your latest edits are saved continuously, so a sudden power cut does not wipe out an hour of typing', 'd'),
  (12, 'Application Software & OS', 'medium', 'What is the purpose of Windows Security / Antivirus software on a PC?', 'To edit birthday videos', 'To detect and block harmful malware or infected downloads before they damage your files', 'To clean physical dust off the keyboard', 'To design school logos', 'b'),
  (12, 'Application Software & OS', 'medium', 'Why do phones and laptops let you turn off unnecessary "Startup Apps" in Settings?', 'It turns off the screen color', 'It uninstalls those apps permanently', 'Fewer heavy apps launching automatically at boot makes the computer start up faster and saves memory', 'It disables the keyboard', 'c'),
  (12, 'Application Software & OS', 'medium', 'When you download a `.zip` archive of club photos, why should you "Extract All" before editing the photos inside?', 'Extracting unpacks the compressed files into a normal folder so apps can open and save changes properly', 'Zip files vanish after 5 minutes', 'Extracting doubles photo resolution', 'Otherwise the photos turn black and white', 'a'),
  (12, 'Application Software & OS', 'medium', 'What does "Version History" in Google Docs, Slides, or Sheets let a student team do?', 'See earlier saved versions of a document and restore work if someone accidentally erased a section', 'See every website visited on the computer', 'Check the laptop manufacturing year', 'Speed up the CPU', 'a'),
  (12, 'Application Software & OS', 'medium', 'If you copy a song file onto your Desktop as a "Shortcut" (tiny arrow on the icon) and then copy ONLY that shortcut to a pendrive, what happens at school?', 'It plays twice as loud', 'It will NOT play, because a shortcut is only a pointer link — not the actual `.mp3` song file itself!', 'It converts the song into a video', 'It copies your entire computer', 'b'),
  (12, 'Application Software & OS', 'medium', 'What is a `.csv` (Comma-Separated Values) file commonly used for between apps like Excel, Google Sheets, and portals?', 'Recording voice notes', 'Editing photo brightness', 'Importing or exporting simple clean rows and columns of table data (like student lists or questions)', 'Playing 3D animations', 'c'),
  (12, 'Application Software & OS', 'medium', 'On a phone or computer, what is the difference between "Clearing App Cache" and "Clearing App Data / Storage"?', 'Neither frees any space', 'Both uninstall the operating system', 'Clearing Cache deletes all your contacts', 'Clearing Cache removes temporary files safely; Clearing Data resets the app like a fresh install and logs you out', 'd'),
  (12, 'Application Software & OS', 'hard', 'Why is "Restarting" a computer sometimes more helpful than "Shut Down and Turn On" when fixing a minor software glitch?', 'Restart charges the battery to 100%', 'Restart upgrades the monitor size', 'Restart deletes old emails', 'Restart performs a clean full reload of the operating system and drivers from scratch', 'd'),
  (12, 'Application Software & OS', 'hard', 'What does "Cloud Sync" (like Google Drive, OneDrive, or Google Photos backup) protect you from?', 'Running out of printer ink', 'Losing your important school projects or photos if your phone or pendrive gets lost or damaged', 'Screen scratches if dropped', 'Keyboard key dust', 'b'),
  (12, 'Application Software & OS', 'hard', 'When printing a 20-page document and you only need Page 3 and Page 4, what should you choose in the Print dialog?', 'Turn off the printer mid-way', 'Print all 20 pages and throw 18 away', 'Select "Custom Pages" and type `3-4` so you do not waste 18 extra sheets of paper', 'Delete the other 18 pages from your original file', 'c'),
  (12, 'Application Software & OS', 'hard', 'What does "Portrait" vs "Landscape" orientation mean when printing a certificate or poster?', 'Portrait is tall/vertical (like a book page); Landscape is wide/horizontal (like a certificate)', 'Portrait is color; Landscape is black-and-white', 'Both print sideways', 'Portrait prints only faces; Landscape prints only trees', 'a'),
  (12, 'Web Browsing & Internet', 'easy', 'What is Google Drive or Microsoft OneDrive an example of?', 'Cloud storage — lets you save files online and open or share them from any phone or computer', 'An offline painting program', 'A computer cooling pad', 'A physical pendrive inside your pocket', 'a'),
  (12, 'Web Browsing & Internet', 'easy', 'When sharing a Google Drive project link with your teacher, why should you check whether access is set to "Restricted" vs "Anyone with the link can View"?', 'If left "Restricted", your teacher will see "Access Denied" when clicking your submitted link!', 'Restricted links delete the file', 'View access lets anyone delete your account', 'Links only work on Sundays', 'a'),
  (12, 'Web Browsing & Internet', 'easy', 'On a noisy browser tab playing unexpected music, what does the tiny speaker icon on that tab let you see or do?', 'Record your microphone', 'Spot immediately which tab is playing sound and even mute that tab', 'Print the tab', 'Bookmark the website', 'b'),
  (12, 'Web Browsing & Internet', 'easy', 'What does an email ending in `.edu.in`, `.ac.in`, or `.gov.in` in India tell you about the website/sender?', 'It is a gaming server', 'It only works without internet', 'It belongs to a verified Indian educational institution (`.edu.in`/`.ac.in`) or government body (`.gov.in`)', 'Anyone can buy it anonymously for ₹10 without verification', 'c'),
  (12, 'Web Browsing & Internet', 'easy', 'If you start writing an email in Gmail and close the tab before clicking Send, where is your unfinished message saved automatically?', 'Starred', 'Sent', 'Spam', 'Drafts', 'd'),
  (12, 'Web Browsing & Internet', 'easy', 'What is a "Browser Extension" (or Add-on)?', 'An extra long charging cable', 'A second monitor screen', 'A Wi-Fi booster antenna', 'A small optional helper tool added inside your browser (which you should install ONLY from trusted creators)', 'd'),
  (12, 'Web Browsing & Internet', 'easy', 'If you want to save an online exam admit card or receipt neatly so you can view it offline anytime without internet, what can you select in the Print (`Ctrl + P`) destination menu?', 'Bluetooth Speaker', 'Save as PDF', 'Fax Machine', 'Delete Page', 'b'),
  (12, 'Web Browsing & Internet', 'medium', 'When a random flashy website suddenly asks "Allow this site to send you Notifications?", what is the smart habit if you do not need alerts from it?', 'Restart your router', 'Always click Allow on every site', 'Click "Block" — allowing shady sites to send notifications floods your screen with fake virus/ad pop-ups!', 'Enter your phone number', 'c'),
  (12, 'Web Browsing & Internet', 'medium', 'When sending an email announcement to 50 parents or students who do not know each other, why is `BCC` better than `CC`?', '`BCC` (Blind Carbon Copy) keeps everyone’s email address private from the other recipients', '`BCC` allows larger attachments', '`CC` deletes the email after reading', '`BCC` makes the email arrive faster', 'a'),
  (12, 'Web Browsing & Internet', 'medium', 'In an email thread sent to 40 club members, what happens if you click "Reply All" instead of "Reply"?', 'Your reply goes to ALL 40 people in the group instead of just the sender!', 'It replies only to yourself', 'It deletes all previous emails', 'It translates your message', 'a'),
  (12, 'Web Browsing & Internet', 'medium', 'Look closely at two URLs: `https://sbi.co.in` vs `https://sbi-login-kyc.freehost.xyz`. In the second URL, which company actually owns the real website domain?', 'State Bank of India', '`freehost.xyz` — the `sbi-login-kyc` part at the front is just a fake subdomain trick!', 'Google', 'Reserve Bank of India', 'b'),
  (12, 'Web Browsing & Internet', 'medium', 'If a webpage looks broken or keeps showing an outdated version even after refreshing, what browser step usually fixes it?', 'Uninstalling Microsoft Word', 'Lowering speaker volume', 'Hard Refresh (`Ctrl + F5`) or clearing cached images and files for that site', 'Replacing the mouse', 'c'),
  (12, 'Web Browsing & Internet', 'medium', 'In Chrome/Edge, why is creating separate "Browser Profiles" helpful when two siblings share one home laptop?', 'It makes Wi-Fi free', 'It creates two physical screens', 'It doubles the laptop hard disk size', 'Each sibling gets their own separate bookmarks, history, and logged-in school accounts without mixing them up', 'd'),
  (12, 'Web Browsing & Internet', 'medium', 'Why shouldn’t you blindly trust a shortened mystery link (like `bit.ly/3xYz99`) sent by an unknown stranger?', 'Short links only work on desktop PCs', 'Short links use 10 GB of data', 'Short links turn off Bluetooth', 'Shortened links hide the real destination website URL until clicked, so they can disguise phishing or scam sites', 'd'),
  (12, 'Web Browsing & Internet', 'hard', 'When sharing a Google Doc with a teammate, what is the difference between giving "Commenter" access vs "Editor" access?', 'An Editor cannot type anything', 'A Commenter can suggest notes without changing your original text; an Editor can directly change or delete content', 'A Commenter cannot even read the document', 'Both are identical', 'b'),
  (12, 'Web Browsing & Internet', 'hard', 'Why do most email services (like Gmail) stop direct attachments larger than 25 MB, and how do you send a 200 MB project video cleanly?', 'Videos can never be shared online', 'Cut the video into 200 separate 1-second emails', 'Email inboxes aren’t built for huge files — upload the video to Google Drive/OneDrive and share its link instead', 'Rename `.mp4` to `.txt` so it shrinks to zero', 'c'),
  (12, 'Web Browsing & Internet', 'hard', 'What does "Pinning a Tab" (Right-click tab → Pin) do in Chrome, Edge, or Firefox?', 'Shrinks the tab neatly to the far left without a close (✕) button so you don’t close it by accident', 'Sends the tab to your friends', 'Downloads every image on the page', 'Prints the tab on paper', 'a'),
  (12, 'Web Browsing & Internet', 'hard', 'When you hover your mouse over a button or link (without clicking yet), where does the browser preview the real destination URL?', 'In the bottom-left corner of the browser window', 'Behind the laptop screen', 'Inside the Recycle Bin', 'On the keyboard', 'a'),
  (12, 'Basic Networking & Connectivity', 'easy', 'On a laptop connected to someone’s mobile Hotspot, turning ON "Metered Connection" (or Data Saver) helps because:', 'It pauses huge background Windows updates so your friend’s mobile data does not drain suddenly', 'It makes the screen brighter', 'It doubles keyboard speed', 'It uninstalls browsers', 'a'),
  (12, 'Basic Networking & Connectivity', 'easy', 'On modern dual-band home Wi-Fi routers, you often see two Wi-Fi names: `Home_2.4G` and `Home_5G`. What is the practical difference?', '`5G` Wi-Fi requires a 5G SIM card inside the router', '`5 GHz` gives faster speeds nearby in the same room; `2.4 GHz` reaches farther through walls', 'There is no difference at all', '`2.4G` works only at 2:40 PM', 'b'),
  (12, 'Basic Networking & Connectivity', 'easy', 'What is "Quick Share / Nearby Share / AirDrop" on modern phones and laptops used for?', 'Deleting duplicate contacts', 'Scanning paper books', 'Sending photos or project files fast between two nearby devices wirelessly without wasting internet data', 'Charging another phone from 10 meters away', 'c'),
  (12, 'Basic Networking & Connectivity', 'easy', 'Why should you avoid logging into banking or sensitive accounts on an open, password-free public Wi-Fi at a railway station or café?', 'Public Wi-Fi deletes SIM contacts', 'Public Wi-Fi breaks your phone camera', 'Public Wi-Fi drains battery 10x faster', 'Unsecured open Wi-Fi networks make it easier for attackers nearby to snoop on traffic or set up fake twin hotspots', 'd'),
  (12, 'Basic Networking & Connectivity', 'easy', 'In online video calls or multiplayer games, what does "High Ping / High Latency" (e.g., 450 ms instead of 25 ms) feel like?', 'Extra crisp sound quality', 'Higher screen brightness', 'More storage space', 'A noticeable delay or lag between clicking/speaking and getting a response back', 'd'),
  (12, 'Basic Networking & Connectivity', 'easy', 'What brings ultrahigh-speed broadband into modern schools and homes using hair-thin strands of glass carrying pulses of light?', 'VGA Monitor Cable', 'Fiber-Optic Cable', 'Aux Audio Cable', 'Printer Ribbon', 'b'),
  (12, 'Basic Networking & Connectivity', 'easy', 'If the home internet suddenly stops working on ALL phones and laptops at once, what safe 1-minute step often resolves a stuck router?', 'Cut the fiber cable', 'Factory-reset every phone in the house', 'Power-cycle the router: turn it OFF, wait 15–30 seconds, and turn it back ON', 'Reinstall Windows', 'c'),
  (12, 'Basic Networking & Connectivity', 'medium', 'What does "NFC" (Near Field Communication) on modern phones and smart cards allow?', 'Tap-to-pay or instant pairing when held within a few centimeters of a reader/tag', 'Printing paper documents', 'Cooling the battery', 'Long-distance satellite TV reception', 'a'),
  (12, 'Basic Networking & Connectivity', 'medium', 'When you type `mapleskhatauli.com` in your browser, which behind-the-scenes internet phonebook translates that friendly name into the server’s numeric IP address?', 'DNS (Domain Name System)', 'UPS (Power Supply)', 'USB (Serial Bus)', 'PDF (Document Format)', 'a'),
  (12, 'Basic Networking & Connectivity', 'medium', 'Your internet speed test shows `100 Mbps` (Megabits per second). Since 8 bits = 1 Byte, roughly how many Megabytes (`MB`) can download in 1 second?', 'Exactly 800 MB per second', 'Around 12.5 MB per second (`100 ÷ 8`)', '0.1 MB per second', '100 GB per second', 'b'),
  (12, 'Basic Networking & Connectivity', 'medium', 'Why is setting up a separate "Guest Wi-Fi" network on a home or school router a smart security practice for visitors?', 'Guest Wi-Fi doubles your ISP plan speed', 'Guest Wi-Fi works 5 km away', 'Visitors get internet access while keeping your main school/home computers and shared printers isolated and private', 'Guest Wi-Fi needs no electricity', 'c'),
  (12, 'Basic Networking & Connectivity', 'medium', 'What is "USB Tethering" between a smartphone and a desktop PC that has no Wi-Fi adapter?', 'Formatting the phone', 'Printing photos directly from SIM card', 'Tying the phone to the desk with a rope', 'Sharing your phone’s internet connection directly to the desktop PC through a normal USB charging/data cable!', 'd'),
  (12, 'Basic Networking & Connectivity', 'medium', 'What is the role of a "Firewall" in Windows or a school router?', 'It prevents physical fire in the computer room', 'It heats up the CPU in winter', 'It deletes old browser bookmarks', 'It monitors incoming and outgoing network traffic and blocks unauthorized outside connections', 'd'),
  (12, 'Basic Networking & Connectivity', 'medium', 'Why should you change the default admin login (`admin / admin`) printed on the bottom sticker of a new home Wi-Fi router?', 'Default passwords use more electricity', 'Anyone connected nearby who knows common default logins could open router settings and change your Wi-Fi or DNS!', 'Otherwise Wi-Fi turns off after 24 hours', 'It voids the monitor warranty', 'b'),
  (12, 'Basic Networking & Connectivity', 'hard', 'When setting a Wi-Fi security type on a modern router, why should you pick `WPA2` or `WPA3` instead of `"Open"` or old `"WEP"`?', 'Security settings only change router LED color', '`Open` is the most secure setting', '`WPA2` / `WPA3` strongly encrypt your wireless Wi-Fi traffic, whereas Open/WEP are insecure', '`WPA3` blocks your own laptop from connecting', 'c'),
  (12, 'Basic Networking & Connectivity', 'hard', 'During a live Zoom/Google Meet class on weak internet, turning OFF your own HD video feed when not speaking helps audio stay clear because:', 'Live video uses much more bandwidth than voice, so pausing video leaves enough bandwidth for smooth audio', 'Microphones stop working when cameras are on', 'Audio does not use the internet', 'Webcams block the speakers physically', 'a'),
  (12, 'Basic Networking & Connectivity', 'hard', 'What is the difference between a Modem (ONT) and a Wi-Fi Router (often combined into one box today)?', 'The Modem connects to the ISP’s outside fiber/cable line; the Router shares that internet across all your home devices', 'The Modem prints paper; the Router scans paper', 'The Router works without a Modem or ISP line', 'Modems are only for Bluetooth earbuds', 'a'),
  (12, 'Basic Networking & Connectivity', 'hard', 'Where is the single best place in a house to keep a Wi-Fi router for even signal coverage across rooms?', 'Locked inside a thick steel almirah', 'In a central, open, slightly elevated spot — NOT hidden inside a closed metal cupboard or corner floor', 'Outside in the rain', 'Directly behind a microwave oven on the floor', 'b'),
  (12, 'Social Ethics & Cyber Safety', 'easy', 'Why do phones and Windows regularly release "Security Updates"?', 'Only to change icon colors', 'To patch newly discovered security holes so hackers and malware cannot exploit them', 'To erase your photos', 'To slow down your internet', 'b'),
  (12, 'Social Ethics & Cyber Safety', 'easy', 'If a classmate accidentally left their Gmail open on a school lab computer, what is the ONLY ethical thing to do?', 'Send a prank email from their account', 'Change their account password', 'Immediately click "Sign Out" without reading a single email, and politely let them know to be careful next time', 'Read their private emails for fun', 'c'),
  (12, 'Social Ethics & Cyber Safety', 'easy', 'Sometimes AI chatbots confidently make up a fake book title, date, or fact that sounds very believable. What should you do before putting AI facts into a school project?', 'Turn off spell check', 'Never read what you submit', 'Assume computers can never be wrong', 'Verify important facts, dates, and quotes from a reliable textbook or trusted official website', 'd'),
  (12, 'Social Ethics & Cyber Safety', 'easy', 'Why is keeping phones on silent and putting screens away at least 30–45 minutes before sleep recommended by doctors?', 'Phones stop working after 10 PM', 'Night Wi-Fi costs double', 'Batteries charge only when silent', 'Bright late-night screens and endless notifications disturb deep sleep and leave you tired in class the next morning', 'd'),
  (12, 'Social Ethics & Cyber Safety', 'easy', 'If you receive an uncomfortable, threatening, or scam message from an unknown account online, what 3 steps protect you best?', 'Click every link they sent', 'Do NOT reply or argue — take a screenshot as proof if needed, Block/Report the account, and tell a trusted parent or teacher', 'Send them your phone number to argue back', 'Keep it secret and worry alone', 'b'),
  (12, 'Social Ethics & Cyber Safety', 'easy', 'What is "Plagiarism" in school projects and digital work?', 'Checking spelling in Word', 'Saving a backup copy on a pendrive', 'Copying someone else’s article, code, or artwork and presenting it as your own original work without credit', 'Using open-source software legally', 'c'),
  (12, 'Social Ethics & Cyber Safety', 'easy', 'When sitting at a computer desk for an hour, what healthy posture avoids neck and back ache?', 'Sit upright with feet flat, shoulders relaxed, and top of the screen near eye level rather than hunching low', 'Twist sideways on one leg', 'Keep the monitor on the floor', 'Bend your neck 90 degrees inches from the keyboard', 'a'),
  (12, 'Social Ethics & Cyber Safety', 'medium', 'What is India’s official national Cyber Crime Helpline number (and portal `cybercrime.gov.in`) in case a family member faces online financial fraud?', '1930', '101', '108', '139', 'a'),
  (12, 'Social Ethics & Cyber Safety', 'medium', 'What is a "Deepfake" video or voice clip that everyone on social media needs to be aware of today?', 'A high-resolution underwater nature video', 'An AI-manipulated video or cloned voice that makes a real person appear to say or do something they NEVER actually did', 'An encrypted ZIP file', 'A backup stored deep inside a folder', 'b'),
  (12, 'Social Ethics & Cyber Safety', 'medium', 'Someone calls your parent in panic using a realistic-sounding voice saying "Send ₹10,000 urgently to this new number, don’t tell anyone!" What is the smart verification habit?', 'Share bank OTPs on the call', 'Install a screen-sharing app they suggest', 'Pause, hang up, and call the family member directly on their REAL known phone number to verify before sending a rupee!', 'Transfer money within 10 seconds in panic', 'c'),
  (12, 'Social Ethics & Cyber Safety', 'medium', 'Why do scammers urgently ask victims to install remote screen-sharing apps (like AnyDesk / TeamViewer / unknown `.apk`s) during fake "KYC / customer care" calls?', 'Banks require AnyDesk for every account', 'To double your mobile battery life', 'To clean dust from your phone speaker', 'Because screen-sharing lets the scammer see your live phone screen, including incoming bank OTPs and apps!', 'd'),
  (12, 'Social Ethics & Cyber Safety', 'medium', 'When designing a club registration form (Data Minimization principle), which information is ethical and sensible to collect?', 'Parents’ bank account numbers and Aadhaar passwords', 'Home Wi-Fi passwords of every student', 'Personal email passwords', 'Only what is genuinely needed for the club (Name, Roll No, Class, Section) — never unnecessary private family/financial data!', 'd'),
  (12, 'Social Ethics & Cyber Safety', 'medium', 'What does a "Creative Commons (CC)" license on an online photo or music track tell students making a video project?', 'Nobody is allowed to view the image', 'The creator has given clear permission to reuse the work under stated conditions (such as giving proper attribution/credit)', 'The file contains a virus', 'You can sell it as your own painting without credit', 'b'),
  (12, 'Social Ethics & Cyber Safety', 'medium', 'What should families do with old dead batteries, broken chargers, and discarded electronics ("E-Waste") instead of burning them or tossing them in open drains?', 'Break screens with a hammer in class', 'Burn plastic circuit boards in the backyard', 'Hand them over to authorized E-Waste collection/recycling centers so toxic metals don’t pollute soil and water', 'Throw batteries into rivers', 'c'),
  (12, 'Social Ethics & Cyber Safety', 'hard', 'Why do social media "recommendation algorithms" create an "Echo Chamber" if you are not mindful?', 'They keep showing more of whatever you clicked before, which can make one-sided opinions or rumors look like the whole truth', 'They delete posts older than 1 hour', 'They turn off Wi-Fi in closed rooms', 'They make your phone speaker echo loudly', 'a'),
  (12, 'Social Ethics & Cyber Safety', 'hard', 'Before posting a close-up photo of your house keys, boarding pass barcode, or school exam admit card barcode publicly on Instagram/status, why should you pause?', 'Visible QR codes, barcodes, roll/application IDs, and personal details in photos can be scanned and misused by strangers!', 'Barcodes blur camera lenses', 'Social media bans white paper', 'There is no privacy risk at all', 'a'),
  (12, 'Social Ethics & Cyber Safety', 'hard', 'What is "Ransomware", and what single everyday habit best protects your school/home projects against it?', 'A free antivirus tool from Microsoft', 'Malware that locks files and demands money — keeping regular offline/cloud backups and avoiding shady downloads protects you!', 'A fast fiber router', 'A type of gaming keyboard', 'b'),
  (12, 'Social Ethics & Cyber Safety', 'hard', 'What does true "Accessibility" mean when students build a website or poster for the school community?', 'Making buttons 2 pixels small', 'Locking the site so nobody can open it', 'Using clear readable fonts, strong color contrast, and image descriptions (`alt` text) so everyone — including people with low vision — can use it comfortably', 'Using tiny light-yellow text on a white background', 'c');
